template<class C>Status text(C& c,const char* name,StableId& value){c.field(name,value);return c.status().ok&&value.empty()?c.reject("StudyCapabilityReferenceMissing",name):c.status();}
template<class C>Status rule(C& c,ActorFoundationRuleRef& value){text(c,"id",value.id);c.field("version",value.version);text(c,"catalog_digest",value.catalog_digest);return c.status().ok&&value.version<1?c.reject("StudyCapabilityRuleVersionInvalid"):c.status();}
template<class C>Status moment(C& c,WorldMoment& value){if constexpr(std::is_same_v<std::decay_t<C>,CodecVisitor>)(void)0;EncodedWorldMoment wire;if(!c.reading()){auto encoded=encode_world_moment(value);if(!encoded.ok)return {false,{},encoded.error};wire=std::move(encoded.value);}c.field("half_day_tick",wire.half_day_tick);c.object("sub_half_day",[&](auto& x){x.field("numerator",wire.sub_half_day.numerator);return x.field("denominator",wire.sub_half_day.denominator);});if(c.reading()&&c.status().ok){auto decoded=decode_world_moment(wire);if(!decoded.ok)return {false,{},decoded.error};value=std::move(decoded.value);}return c.status();}
template<class C>Status source(C& c,SourceRef& value){text(c,"domain",value.domain);text(c,"kind",value.kind);return text(c,"id",value.id);}
template<class C>Status condition(C& c,CharacterConditionSourceRef& value){Integer tag=static_cast<Integer>(value.index());c.field("tag",tag);if(tag<0||tag>1)return c.reject("StudyConditionSourceKindInvalid");if(c.reading())value=tag==0?CharacterConditionSourceRef{InitialConditionSeedRef{}}:CharacterConditionSourceRef{ConditionReceiptRefV2{}};return tag==0?text(c,"seed_key",std::get<InitialConditionSeedRef>(value).seed_key):text(c,"result_id",std::get<ConditionReceiptRefV2>(value).result_id);}
template<class C>Status component(C& c,CharacterEfficiencyComponent& value){Integer tag=static_cast<Integer>(value.kind);c.field("component_kind",tag);if(tag<0||tag>2)return c.reject("StudyEfficiencyKindInvalid");if(tag==2)return c.reject("StudyDiseaseEfficiencySourceRequired");if(c.reading())value.kind=static_cast<CharacterEfficiencyComponent::Kind>(tag);c.object("original_source_ref",[&](auto& x){return condition(x,value.original_source_ref);});c.object("rule_ref",[&](auto& x){return rule(x,value.rule_ref);});c.field("cap_bp",value.cap_bp);return c.status().ok&&(value.cap_bp<0||value.cap_bp>10000)?c.reject("StudyEfficiencyCapInvalid"):c.status();}
template<class C>Status frozen(C& c,FrozenLessonCapability& value){text(c,"actor_id",value.actor_id);c.object("purpose_ref",[&](auto& x){return rule(x,value.purpose_ref);});c.field("condition_revision",value.condition_revision);text(c,"origin_ref",value.origin_ref);c.sequence("attribute_milestone_refs",value.attribute_milestone_refs,[](auto& x,auto& ref){return text(x,"value",ref);});c.sequence("condition_source_refs",value.condition_source_refs,[](auto& x,auto& ref){return condition(x,ref);});c.sequence("registered_efficiency_components",value.registered_efficiency_components,[](auto& x,auto& ref){return component(x,ref);});c.field("frozen_efficiency_bp",value.frozen_efficiency_bp);c.object("admission_rule_ref",[&](auto& x){return rule(x,value.admission_rule_ref);});return c.status().ok&&(value.condition_revision<0||value.frozen_efficiency_bp<0||value.frozen_efficiency_bp>10000||value.origin_ref!=value.actor_id||(value.purpose_ref.id!="study"&&value.purpose_ref.id!="provide_teaching"))?c.reject("FrozenLessonCapabilityInvalid"):c.status();}
template<class C>Status row(C& c,LessonCapabilitySource& value){text(c,"action_id",value.action_id);c.field("lesson_ordinal",value.lesson_ordinal);c.object("work_period_ref",[&](auto& x){auto& r=value.work_period_ref;text(x,"action_id",r.action_id);x.field("lesson_ordinal",r.lesson_ordinal);x.object("original_fsl_source",[&](auto& y){return source(y,r.original_fsl_source);});return x.field("source_schema",r.source_schema);});c.object("provided_from",[&](auto& x){return moment(x,value.provided_from);});c.object("provided_to",[&](auto& x){return moment(x,value.provided_to);});c.object("student_capability",[&](auto& x){return frozen(x,value.student_capability);});c.optional("teacher_capability",value.teacher_capability,[](auto& x,auto& v){return frozen(x,v);});c.object("xp_rule_ref",[&](auto& x){return rule(x,value.xp_rule_ref);});c.optional("innate_source_ref",value.innate_source_ref,[](auto& x,auto& v){x.object("owner_ref",[&](auto& y){return source(y,v.owner_ref);});return text(x,"field_selector",v.field_selector);});c.sequence("fatigue_effect_use_refs",value.fatigue_effect_use_refs,[](auto& x,auto& v){return source(x,v);});c.object("student_condition_receipt_ref",[&](auto& x){return text(x,"result_id",value.student_condition_receipt_ref.result_id);});c.optional("teacher_condition_receipt_ref",value.teacher_condition_receipt_ref,[](auto& x,auto& v){return text(x,"result_id",v.result_id);});c.object("original_lesson_result_ref",[&](auto& x){text(x,"action_id",value.original_lesson_result_ref.action_id);return x.field("lesson_ordinal",value.original_lesson_result_ref.lesson_ordinal);});if(!c.status().ok)return c.status();const auto& ref=value.work_period_ref;if(value.lesson_ordinal<1||value.lesson_ordinal>6||ref.action_id!=value.action_id||ref.lesson_ordinal!=value.lesson_ordinal||ref.source_schema!=1||ref.original_fsl_source.domain!="growth"||ref.original_fsl_source.kind!="growth_fixed_service_boundary"||value.original_lesson_result_ref.action_id!=value.action_id||value.original_lesson_result_ref.lesson_ordinal!=value.lesson_ordinal||bool(value.teacher_capability)!=bool(value.teacher_condition_receipt_ref)||value.fatigue_effect_use_refs.size()>16)return c.reject("LessonCapabilitySourceShapeInvalid");auto compared=compare_world_moments(value.provided_from,value.provided_to);if(!compared.ok)return {false,{},compared.error};return compared.value>=0?c.reject("LessonCapabilitySourceWindowInvalid"):c.status();}
